const pipe = (...fns) => (input) => fns.reduce((value, fn) => fn(value), input);
const compose = (...fns) => (input) => fns.reduceRight((value, fn) => fn(value), input);

const trim = (s) => s.trim();
const lower = (s) => s.toLowerCase();
const slug = (s) => s.replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

const toSlug = pipe(trim, lower, slug);        // trim first, slug last
const same = compose(slug, lower, trim);       // identical behaviour

toSlug("  Hello, World!  ");  // "hello-world"

const truncate = (max) => (s) => s.slice(0, max);
const prefix = (text) => (s) => text + s;

const toId = pipe(trim, lower, slug, truncate(11), prefix("post-"));
toId("  A Very Long Blog Post Title ");  // "post-a-very-long"

// pipe() with no steps is the identity function:
pipe()("unchanged");  // "unchanged"
